-- Panda Wok D1 schema.
-- Generated by scripts/d1/generate-schema.py from the live Postgres schema.
--   uuid/vector/citext/text[] -> TEXT (arrays as JSON), timestamptz/date -> TEXT ISO-8601 UTC,
--   jsonb -> TEXT (JSON), bool -> INTEGER 0/1, int2/4/8 -> INTEGER, numeric/float -> REAL.
--   enums -> TEXT + CHECK. Money stays REAL (float64) so a price reads back exactly as written.

PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS "restaurants" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))),
  "slug" TEXT NOT NULL,
  "name_en" TEXT NOT NULL,
  "name_ar" TEXT,
  "tagline_en" TEXT,
  "tagline_ar" TEXT,
  "description_en" TEXT,
  "description_ar" TEXT,
  "story_md" TEXT,
  "cuisine_tags" TEXT NOT NULL DEFAULT '[]',
  "city" TEXT,
  "area" TEXT,
  "country" TEXT DEFAULT 'Egypt',
  "latitude" REAL,
  "longitude" REAL,
  "phone" TEXT,
  "whatsapp" TEXT,
  "email" TEXT,
  "social" TEXT NOT NULL DEFAULT '{}',
  "opening_hours" TEXT NOT NULL DEFAULT '{}',
  "currency" TEXT NOT NULL DEFAULT 'EGP',
  "is_active" INTEGER NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "categories" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))),
  "name_en" TEXT NOT NULL,
  "name_ar" TEXT,
  "slug" TEXT NOT NULL,
  "description_en" TEXT,
  "description_ar" TEXT,
  "image_url" TEXT,
  "seo_title" TEXT,
