  "display_name" TEXT,
  "is_active" INTEGER NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "login_id" TEXT,
  PRIMARY KEY ("user_id")
);

CREATE TABLE IF NOT EXISTS "orders" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))),
  "order_number" TEXT NOT NULL,
  "idempotency_key" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "status" TEXT CHECK ("status" IN ('new', 'accepted', 'in_progress', 'prepared', 'out_for_delivery', 'finished', 'canceled', 'rejected', 'failed', 'refunded')) NOT NULL DEFAULT 'new',
  "fulfillment" TEXT CHECK ("fulfillment" IN ('delivery', 'pickup')) NOT NULL DEFAULT 'delivery',
  "payment_method" TEXT CHECK ("payment_method" IN ('cash_on_delivery', 'card_on_delivery', 'online', 'instapay')) NOT NULL DEFAULT 'cash_on_delivery',
  "payment_status" TEXT CHECK ("payment_status" IN ('unpaid', 'authorized', 'paid', 'refunded', 'failed')) NOT NULL DEFAULT 'unpaid',
  "currency" TEXT NOT NULL DEFAULT 'EGP',
  "subtotal" REAL NOT NULL DEFAULT 0,
  "discount_total" REAL NOT NULL DEFAULT 0,
  "delivery_fee" REAL NOT NULL DEFAULT 0,
  "tax_total" REAL NOT NULL DEFAULT 0,
  "total" REAL NOT NULL DEFAULT 0,
  "points_redeemed" INTEGER NOT NULL DEFAULT 0,
  "points_earned" INTEGER NOT NULL DEFAULT 0,
  "address_snapshot" TEXT,
  "customer_note" TEXT,
  "eta_minutes" INTEGER,
  "cancel_reason" TEXT,
  "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "accepted_at" TEXT,
  "prepared_at" TEXT,
  "dispatched_at" TEXT,
  "finished_at" TEXT,
  "canceled_at" TEXT,
  "restaurant_id" TEXT NOT NULL,
  "offer_id" TEXT,
  "offer_name" TEXT,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "order_items" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))),
  "order_id" TEXT NOT NULL,
