CREATE TABLE IF NOT EXISTS "order_status_history" (
  "id" INTEGER NOT NULL,
  "order_id" TEXT NOT NULL,
  "from_status" TEXT CHECK ("from_status" IN ('new', 'accepted', 'in_progress', 'prepared', 'out_for_delivery', 'finished', 'canceled', 'rejected', 'failed', 'refunded')),
  "to_status" TEXT CHECK ("to_status" IN ('new', 'accepted', 'in_progress', 'prepared', 'out_for_delivery', 'finished', 'canceled', 'rejected', 'failed', 'refunded')) NOT NULL,
  "changed_by" TEXT,
  "changed_by_role" TEXT CHECK ("changed_by_role" IN ('owner', 'admin', 'manager', 'kitchen', 'support', 'marketing')),
  "note" TEXT,
  "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "notifications" (
  "id" INTEGER NOT NULL,
