CREATE TABLE IF NOT EXISTS "exports" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))),
  "dataset" TEXT NOT NULL,
  "format" TEXT CHECK ("format" IN ('csv', 'json', 'xlsx', 'txt')) NOT NULL DEFAULT 'csv',
  "filters" TEXT NOT NULL DEFAULT '{}',
  "status" TEXT CHECK ("status" IN ('queued', 'running', 'ready', 'failed', 'expired')) NOT NULL DEFAULT 'queued',
  "row_count" INTEGER,
  "storage_path" TEXT,
  "bytes" INTEGER,
  "error" TEXT,
  "requested_by" TEXT,
  "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "completed_at" TEXT,
  "expires_at" TEXT,
  "content" TEXT,
  "content_encoding" TEXT,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "backup_records" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))),
  "kind" TEXT CHECK ("kind" IN ('database', 'configuration', 'menu', 'media_refs', 'snapshot')) NOT NULL,
  "status" TEXT CHECK ("status" IN ('queued', 'running', 'ready', 'failed')) NOT NULL DEFAULT 'queued',
  "label" TEXT,
  "storage_path" TEXT,
  "bytes" INTEGER,
  "manifest" TEXT NOT NULL DEFAULT '{}',
  "error" TEXT,
  "created_by" TEXT,
  "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "completed_at" TEXT,
  "format" TEXT NOT NULL DEFAULT 'json',
  "content" TEXT,
  "content_encoding" TEXT,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "ai_providers" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))),
  "name" TEXT NOT NULL,
  "kind" TEXT NOT NULL DEFAULT 'openai_compatible',
  "base_url" TEXT,
  "model" TEXT,
  "secret_ref" TEXT,
  "is_enabled" INTEGER NOT NULL DEFAULT 0,
  "is_fallback" INTEGER NOT NULL DEFAULT 0,
  "priority" INTEGER NOT NULL DEFAULT 100,
  "monthly_token_quota" INTEGER,
  "max_requests_per_minute" INTEGER NOT NULL DEFAULT 20,
  "config" TEXT NOT NULL DEFAULT '{}',
  "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "routes" TEXT NOT NULL DEFAULT '{}',
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "ai_prompts" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))),
  "key" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "system_instruction" TEXT NOT NULL,
  "temperature" REAL NOT NULL DEFAULT 0.2,
  "max_tokens" INTEGER NOT NULL DEFAULT 700,
  "is_active" INTEGER NOT NULL DEFAULT 1,
  "updated_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_by" TEXT,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "ai_requests" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))),
  "user_id" TEXT,
  "surface" TEXT NOT NULL DEFAULT 'assistant',
  "prompt_key" TEXT,
  "provider" TEXT,
  "model" TEXT,
  "latency_ms" INTEGER,
  "prompt_tokens" INTEGER,
  "completion_tokens" INTEGER,
  "estimated_cost" REAL,
  "status" TEXT NOT NULL DEFAULT 'ok',
  "error" TEXT,
  "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "provider_errors" TEXT,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "ai_usage_daily" (
  "day" TEXT NOT NULL,
  "provider" TEXT NOT NULL DEFAULT 'all',
  "requests" INTEGER NOT NULL DEFAULT 0,
