-- Uniques the app relies on (slug lookup, signup, order idempotency).
CREATE UNIQUE INDEX IF NOT EXISTS "restaurants_slug_key" ON "restaurants"("slug");
CREATE UNIQUE INDEX IF NOT EXISTS "categories_slug_key" ON "categories"("slug");
CREATE UNIQUE INDEX IF NOT EXISTS "menu_items_slug_key" ON "menu_items"("slug");
CREATE UNIQUE INDEX IF NOT EXISTS "menu_items_external_id_key" ON "menu_items"("external_id");
CREATE UNIQUE INDEX IF NOT EXISTS "orders_order_number_key" ON "orders"("order_number");
CREATE UNIQUE INDEX IF NOT EXISTS "orders_idempotency_idx" ON "orders"("user_id", "idempotency_key");
CREATE UNIQUE INDEX IF NOT EXISTS "feature_flags_key" ON "feature_flags"("key");
CREATE UNIQUE INDEX IF NOT EXISTS "settings_key" ON "settings"("key");
CREATE UNIQUE INDEX IF NOT EXISTS "profiles_email_key" ON "profiles"("email");
CREATE UNIQUE INDEX IF NOT EXISTS "profiles_phone_key" ON "profiles"("phone");
CREATE UNIQUE INDEX IF NOT EXISTS "auth_users_email_key" ON "auth_users"("email");
CREATE UNIQUE INDEX IF NOT EXISTS "ai_prompts_key_key" ON "ai_prompts"("key");
CREATE UNIQUE INDEX IF NOT EXISTS "ai_providers_name_key" ON "ai_providers"("name");
CREATE UNIQUE INDEX IF NOT EXISTS "mcp_servers_name_key" ON "mcp_servers"("name");
CREATE UNIQUE INDEX IF NOT EXISTS "customer_tags_key_key" ON "customer_tags"("key");
CREATE UNIQUE INDEX IF NOT EXISTS "team_threads_slug_key" ON "team_threads"("slug");

-- Indexes for the hot read paths.
CREATE INDEX IF NOT EXISTS "menu_items_active_idx" ON "menu_items"("category_id", "sort_order");
CREATE INDEX IF NOT EXISTS "menu_items_featured_idx" ON "menu_items"("is_featured");
CREATE INDEX IF NOT EXISTS "categories_sort_idx" ON "categories"("is_enabled", "sort_order");
CREATE INDEX IF NOT EXISTS "orders_user_idx" ON "orders"("user_id", "created_at");
CREATE INDEX IF NOT EXISTS "orders_status_idx" ON "orders"("status", "created_at");
CREATE INDEX IF NOT EXISTS "orders_created_idx" ON "orders"("created_at");
CREATE INDEX IF NOT EXISTS "order_items_order_idx" ON "order_items"("order_id");
CREATE INDEX IF NOT EXISTS "order_status_history_order_idx" ON "order_status_history"("order_id", "created_at");
CREATE INDEX IF NOT EXISTS "addresses_user_idx" ON "addresses"("user_id", "is_default");
CREATE INDEX IF NOT EXISTS "notifications_user_idx" ON "notifications"("user_id", "created_at");
CREATE INDEX IF NOT EXISTS "messages_conversation_idx" ON "messages"("conversation_id", "created_at");
CREATE INDEX IF NOT EXISTS "menu_images_item_idx" ON "menu_images"("menu_item_id", "sort_order");
CREATE INDEX IF NOT EXISTS "modifier_groups_item_idx" ON "modifier_groups"("menu_item_id");
CREATE INDEX IF NOT EXISTS "modifier_options_group_idx" ON "modifier_options"("group_id");
CREATE INDEX IF NOT EXISTS "analytics_events_created_idx" ON "analytics_events"("created_at");
CREATE INDEX IF NOT EXISTS "activity_logs_created_idx" ON "activity_logs"("created_at");
CREATE INDEX IF NOT EXISTS "audit_logs_created_idx" ON "audit_logs"("created_at");
